#!/usr/bin/env python3
"""Pinned V6 staging payload. No live installation or Telegram sending."""
import base64, hashlib, json, os, subprocess, sys, tempfile, zlib
from pathlib import Path
sys.dont_write_bytecode=True
os.umask(0o077)
PAYLOAD = ''

def main():
    home=Path.home()/'.local/share/gsun-pr'
    work=home/'revisions/gsun-november-2026-v6-final'
    for unit in ('gsun-pr.timer','gsun-pr.service','gsun-pr-prepare.timer','gsun-pr-prepare.service'):
        result=subprocess.run(['systemctl','--user','show',unit,'-p','ActiveState','--value'],capture_output=True,text=True,timeout=10)
        if result.returncode or result.stdout.strip() not in ('inactive','failed'):
            raise SystemExit('STOP_UNIT_NOT_INACTIVE: '+unit)
    with tempfile.TemporaryDirectory(prefix='gsun-v6-review-') as tmp:
        root=Path(tmp)
        for name,content in json.loads(zlib.decompress(base64.b64decode(PAYLOAD))).items():
            if Path(name).name != name: raise SystemExit('STOP_BUNDLE_PATH')
            (root/name).write_text(content)
        sys.path.insert(0,tmp)
        import factory as f, revise as r, stage_v6 as s
        configpath=Path.home()/'.config/gsun-pr/runtime.env'
        config=r.load_env(configpath)
        if config.get('GSUN_GENERATE_ENABLED')=='yes':raise SystemExit('STOP_GENERATION_ENABLED')
        try:
            initial=hashlib.sha256(configpath.read_bytes()).hexdigest()
            ok=s.stage(home,work,f.read(root/'payload.json'),config)
            if hashlib.sha256(configpath.read_bytes()).hexdigest()!=initial:
                (work/'READY.json').unlink(missing_ok=True)
                raise f.Stop('STOP_CONFIG_CHANGED')
            return 0 if ok else 2
        except f.Stop as error:
            (work/'READY.json').unlink(missing_ok=True)
            print(str(error));return 2
        except Exception:
            (work/'READY.json').unlink(missing_ok=True)
            print('V6_STAGE_FAILED — secrets hidden; live plan unchanged');return 2
if __name__=='__main__':sys.exit(main())
